// مولَّد من backend/firebase/firestore.rules بـ npm run rules — لا تعدّله يدوياً
export default "rules_version = '2';\nservice cloud.firestore {\n  match /databases/{db}/documents {\n\n    // ---------- helpers ----------\n    function signedIn() { return request.auth != null; }\n    function me() { return get(/databases/$(db)/documents/users/$(request.auth.uid)).data; }\n    function active() { return signedIn() && me().active == true; }\n    function isCentral() { return active() && me().role == 'CENTRAL'; }\n    function inRegion(rid) { return active() && me().regionId == rid; }\n    function isRegionLead(rid) { return inRegion(rid) && me().role in ['REGION_MANAGER', 'REGION_ADMIN']; }\n    function isRegionManager(rid) { return inRegion(rid) && me().role == 'REGION_MANAGER'; }\n    function isSquareLead(rid, sid) { return inRegion(rid) && me().role == 'SQUARE_MANAGER' && me().squareId == sid; }\n    function inSquare(rid, sid) { return inRegion(rid) && me().squareId == sid; }\n    function lead(rid, sid) { return isCentral() || isRegionLead(rid) || isSquareLead(rid, sid); }\n\n    function str(v, max) { return v is string && v.size() <= max; }\n    function optStr(d, k, max) { return !(k in d) || d[k] == null || str(d[k], max); }\n    function only(keys) { return request.resource.data.diff(resource.data).affectedKeys().hasOnly(keys); }\n    function unchanged(keys) { return !request.resource.data.diff(resource.data).affectedKeys().hasAny(keys); }\n\n    // ---------- users: created and changed only by the Worker (admin) ----------\n    match /users/{uid} {\n      allow read: if signedIn() && (\n        request.auth.uid == uid ||\n        isCentral() ||\n        // للتواصل: الإدارة المركزية للجميع، وقيادات المنطقة لأفرادها، وزملاء المربع لبعضهم\n        (active() && resource.data.role == 'CENTRAL') ||\n        (active() && me().regionId == resource.data.regionId && resource.data.role in ['REGION_MANAGER', 'REGION_ADMIN']) ||\n        (active() && me().regionId == resource.data.regionId && me().squareId != null && me().squareId == resource.data.squareId) ||\n        (active() && me().regionId == resource.data.regionId && (\n          me().role in ['REGION_MANAGER', 'REGION_ADMIN'] ||\n          (me().role == 'SQUARE_MANAGER' && me().squareId == resource.data.squareId))));\n      allow write: if false;\n    }\n\n    // ---------- directory ----------\n    match /regions/{rid} {\n      allow read: if isCentral() || inRegion(rid);\n      allow create, update: if isCentral() && str(request.resource.data.name, 80);\n      allow delete: if isCentral() && resource.data.deletedAt is number;\n    }\n\n    match /squares/{sid} {\n      allow read: if isCentral() || inRegion(resource.data.regionId);\n      allow create: if (isCentral() || isRegionManager(request.resource.data.regionId))\n        && str(request.resource.data.name, 80) && optStr(request.resource.data, 'phone', 20)\n        && optStr(request.resource.data, 'managerName', 80);\n      // نقل المربع بين المناطق للمركزي فقط\n      allow update: if (isCentral() || (isRegionManager(resource.data.regionId) && unchanged(['regionId'])))\n        && str(request.resource.data.name, 80);\n      // الحذف الفعلي فقط لما هو في سلة المهملات\n      allow delete: if (isCentral() || isRegionManager(resource.data.regionId)) && resource.data.deletedAt is number;\n    }\n\n    function families(d) { return !('families' in d) || d.families == null || (d.families is int && d.families >= 0 && d.families <= 100000); }\n    match /camps/{cid} {\n      allow read: if isCentral() || isRegionLead(resource.data.regionId) || inSquare(resource.data.regionId, resource.data.squareId);\n      allow create: if lead(request.resource.data.regionId, request.resource.data.squareId)\n        && str(request.resource.data.name, 80) && optStr(request.resource.data, 'phone', 20)\n        && optStr(request.resource.data, 'managerName', 80) && families(request.resource.data);\n      allow update: if lead(resource.data.regionId, resource.data.squareId)\n        && (unchanged(['regionId', 'squareId']) || isCentral()\n            || (isRegionManager(resource.data.regionId) && request.resource.data.regionId == resource.data.regionId))\n        && str(request.resource.data.name, 80) && families(request.resource.data);\n      allow delete: if lead(resource.data.regionId, resource.data.squareId) && resource.data.deletedAt is number;\n    }\n\n    // ---------- tasks ----------\n    function taskReader(d) {\n      return isCentral() || isRegionLead(d.regionId) || isSquareLead(d.regionId, d.squareId)\n        || (active() && (d.assigneeId == request.auth.uid || d.createdBy == request.auth.uid))\n        // مهام المربع غير المسندة لشخص يراها أفراده، ومهام المخيم يراها المرتبطون به\n        || (inSquare(d.regionId, d.squareId) && d.assigneeId == null)\n        || (active() && d.campId != null && me().campId == d.campId);\n    }\n    function executor(d) {\n      return d.assigneeId == request.auth.uid\n        || (d.assigneeId == null && (inSquare(d.regionId, d.squareId) || (d.campId != null && me().campId == d.campId)));\n    }\n    function validTransition(from, to) {\n      return (from == 'NEW' && to in ['SEEN', 'IN_PROGRESS'])\n        || (from == 'SEEN' && to == 'IN_PROGRESS')\n        || (from == 'IN_PROGRESS' && to == 'AWAITING_REVIEW')\n        || (from == 'AWAITING_REVIEW' && to in ['APPROVED', 'IN_PROGRESS', 'REJECTED'])\n        || (to == 'CANCELLED' && from in ['NEW', 'SEEN', 'IN_PROGRESS', 'AWAITING_REVIEW']);\n    }\n    function assigneeMove(from, to) {\n      return (from == 'NEW' && to in ['SEEN', 'IN_PROGRESS'])\n        || (from == 'SEEN' && to == 'IN_PROGRESS')\n        || (from == 'IN_PROGRESS' && to == 'AWAITING_REVIEW');\n    }\n\n    match /tasks/{tid} {\n      allow read: if taskReader(resource.data);\n\n      allow create: if active() && me().role != 'FIELD_STAFF'\n        && request.resource.data.createdBy == request.auth.uid\n        && request.resource.data.status == 'NEW'\n        && lead(request.resource.data.regionId, request.resource.data.squareId)\n        && str(request.resource.data.title, 120) && request.resource.data.title.size() > 0\n        && str(request.resource.data.description, 1000)\n        && request.resource.data.priority in ['NORMAL', 'HIGH', 'URGENT'];\n\n      allow update: if active() && (\n        // الحذف الناعم والاسترجاع: للإداري فقط ولأي حالة\n        (lead(resource.data.regionId, resource.data.squareId) && only(['deletedAt', 'updatedAt']))\n        ||\n        (!(resource.data.status in ['APPROVED', 'REJECTED', 'CANCELLED'])\n          && unchanged(['createdBy', 'regionId', 'createdAt'])\n          && str(request.resource.data.title, 120) && str(request.resource.data.description, 1000)\n          && (\n            // الإداري ينفّذ أي انتقال صالح ويعدّل بيانات المهمة\n            (lead(resource.data.regionId, resource.data.squareId)\n              && (request.resource.data.status == resource.data.status\n                  || validTransition(resource.data.status, request.resource.data.status)))\n            ||\n            // المُكلَّف يحرّك الحالة للأمام فقط\n            (executor(resource.data)\n              && only(['status', 'updatedAt'])\n              && assigneeMove(resource.data.status, request.resource.data.status))\n          ))\n      );\n\n      allow delete: if active() && lead(resource.data.regionId, resource.data.squareId) && resource.data.deletedAt is number;\n\n      match /events/{eid} {\n        allow read: if taskReader(get(/databases/$(db)/documents/tasks/$(tid)).data);\n        allow create: if taskReader(get(/databases/$(db)/documents/tasks/$(tid)).data)\n          && request.resource.data.actorId == request.auth.uid\n          && request.resource.data.toStatus is string\n          && optStr(request.resource.data, 'note', 500);\n        allow update, delete: if false;\n      }\n\n      match /photos/{pid} {\n        allow read: if taskReader(get(/databases/$(db)/documents/tasks/$(tid)).data);\n        allow create: if taskReader(get(/databases/$(db)/documents/tasks/$(tid)).data)\n          && request.resource.data.by == request.auth.uid\n          && request.resource.data.kind in ['BEFORE', 'AFTER']\n          && str(request.resource.data.data, 400000);\n        allow update: if false;\n        // صاحب الصورة أو إداري المهمة يحذفها\n        allow delete: if active() && (resource.data.by == request.auth.uid\n          || lead(get(/databases/$(db)/documents/tasks/$(tid)).data.regionId, get(/databases/$(db)/documents/tasks/$(tid)).data.squareId));\n      }\n    }\n\n    // ---------- places: points, camps and managers' residences ----------\n    function geo(d) { return d.lat is number && d.lng is number && d.lat >= -90 && d.lat <= 90 && d.lng >= -180 && d.lng <= 180; }\n    match /places/{pid} {\n      allow read: if active() && (isCentral() || (inRegion(resource.data.regionId)\n        && (resource.data.kind != 'HOME' || resource.data.ownerId == request.auth.uid || me().role in ['REGION_MANAGER', 'REGION_ADMIN'])));\n      allow create: if active() && me().role != 'FIELD_STAFF' && geo(request.resource.data)\n        && str(request.resource.data.name, 80) && request.resource.data.name.size() > 0\n        && request.resource.data.kind in ['HOME', 'POINT']\n        && request.resource.data.radius is number && request.resource.data.radius >= 20 && request.resource.data.radius <= 5000\n        && (isCentral() || (request.resource.data.regionId == me().regionId\n          && (request.resource.data.kind == 'HOME' ? request.resource.data.ownerId == request.auth.uid : isRegionLead(request.resource.data.regionId))));\n      allow update, delete: if active() && (isCentral() || (inRegion(resource.data.regionId)\n        && (resource.data.ownerId == request.auth.uid || isRegionLead(resource.data.regionId))));\n    }\n\n    // ---------- check-ins: presence points on the live map ----------\n    match /checkins/{cid} {\n      allow read: if active() && (resource.data.userId == request.auth.uid || isCentral()\n        || isRegionLead(resource.data.regionId) || isSquareLead(resource.data.regionId, resource.data.squareId));\n      allow create: if active() && request.resource.data.userId == request.auth.uid\n        && request.resource.data.regionId == me().regionId && geo(request.resource.data)\n        && request.resource.data.day is string && request.resource.data.at is number;\n      allow update, delete: if false;\n    }\n\n    // ---------- recurring task templates (the Worker materialises them) ----------\n    match /templates/{tid} {\n      allow read: if active() && lead(resource.data.regionId, resource.data.squareId);\n      allow create: if active() && me().role != 'FIELD_STAFF' && request.resource.data.createdBy == request.auth.uid\n        && lead(request.resource.data.regionId, request.resource.data.squareId)\n        && str(request.resource.data.title, 120) && request.resource.data.title.size() > 0\n        && str(request.resource.data.description, 1000)\n        && request.resource.data.every in ['DAILY', 'WEEKLY']\n        && request.resource.data.priority in ['NORMAL', 'HIGH', 'URGENT'];\n      allow update: if active() && lead(resource.data.regionId, resource.data.squareId)\n        && only(['active', 'title', 'description', 'priority', 'every', 'weekday', 'hour', 'assigneeId']);\n      allow delete: if active() && lead(resource.data.regionId, resource.data.squareId);\n    }\n\n    // ---------- weekly reports: written by the Worker ----------\n    match /weekly/{wid} {\n      allow read: if active() && (isCentral() || isRegionLead(resource.data.regionId));\n      allow write: if false;\n    }\n\n    // ---------- chat ----------\n    function isMember(roomId) {\n      return signedIn() && request.auth.uid in get(/databases/$(db)/documents/rooms/$(roomId)).data.members;\n    }\n    function canMessage(other) {\n      return isCentral()\n        || get(/databases/$(db)/documents/users/$(other)).data.role == 'CENTRAL'\n        || get(/databases/$(db)/documents/users/$(other)).data.regionId == me().regionId;\n    }\n\n    match /rooms/{roomId} {\n      // الأعضاء فقط؛ لا يقرأ المدراء المحادثات الخاصة إلا إن كانوا أعضاء\n      allow read: if signedIn() && request.auth.uid in resource.data.members;\n      // غرف المجموعات تُنشأ من الـ Worker فقط لضمان صحة الأعضاء والمنطقة\n      allow create: if active()\n        && request.resource.data.type == 'direct'\n        && request.resource.data.members.size() == 2\n        && request.auth.uid in request.resource.data.members\n        && request.resource.data.members[0] != request.resource.data.members[1]\n        && canMessage(request.resource.data.members[0] == request.auth.uid\n            ? request.resource.data.members[1] : request.resource.data.members[0]);\n      allow update: if signedIn() && request.auth.uid in resource.data.members\n        && only(['lastMessage', 'lastAt']) && optStr(request.resource.data, 'lastMessage', 200);\n      allow delete: if false;\n\n      match /messages/{mid} {\n        allow read: if isMember(roomId);\n        allow create: if isMember(roomId)\n          && request.resource.data.senderId == request.auth.uid\n          && request.resource.data.type in ['text', 'image', 'file', 'location', 'voice']\n          && optStr(request.resource.data, 'text', 4000)\n          && request.resource.data.readBy == [request.auth.uid];\n        // المرسل يحذف رسالته لدى الجميع (تبقى أثراً بلا محتوى)\n        allow update: if (isMember(roomId) && resource.data.senderId == request.auth.uid\n          && request.resource.data.type == 'deleted' && request.resource.data.text == ''\n          && only(['type', 'text', 'media', 'lat', 'lng']))\n          // أو إيصالات القراءة فقط: يضيف المستخدم نفسه إلى readBy\n          || (isMember(roomId)\n          && only(['readBy'])\n          && !(request.auth.uid in resource.data.readBy)\n          && request.resource.data.readBy.size() == resource.data.readBy.size() + 1\n          && request.resource.data.readBy.toSet() == resource.data.readBy.toSet().union([request.auth.uid].toSet()));\n        allow delete: if false;\n      }\n    }\n\n    // ---------- SOS ----------\n    match /sos/{sid} {\n      allow read: if active() && (\n        resource.data.senderId == request.auth.uid || isCentral() ||\n        isRegionLead(resource.data.regionId) || isSquareLead(resource.data.regionId, resource.data.squareId));\n      allow create: if active()\n        && request.resource.data.senderId == request.auth.uid\n        && request.resource.data.regionId == me().regionId\n        && request.resource.data.status == 'OPEN'\n        && optStr(request.resource.data, 'note', 500);\n      allow update: if lead(resource.data.regionId, resource.data.squareId)\n        && only(['status', 'ackBy', 'updatedAt'])\n        && ((resource.data.status == 'OPEN' && request.resource.data.status == 'ACK')\n          || (resource.data.status == 'ACK' && request.resource.data.status == 'RESOLVED'));\n      allow delete: if false;\n    }\n\n    // ---------- audit: written by the Worker only ----------\n    match /audit/{id} {\n      allow read: if isCentral() || isRegionLead(resource.data.regionId);\n      allow write: if false;\n    }\n\n    // ---------- FCM tokens ----------\n    match /devices/{uid} {\n      allow read, write: if signedIn() && request.auth.uid == uid\n        && (request.method == 'delete' || str(request.resource.data.token, 400));\n    }\n\n    // ---------- meetings: rooms created by the Worker, signalling by members ----------\n    function isMeetingMember(mid) {\n      return signedIn() && request.auth.uid in get(/databases/$(db)/documents/meetings/$(mid)).data.members;\n    }\n    match /meetings/{mid} {\n      allow read: if signedIn() && request.auth.uid in resource.data.members;\n      allow write: if false;\n      match /signals/{sid} {\n        allow read: if isMeetingMember(mid) && (resource.data.to == request.auth.uid || resource.data.to == 'all');\n        allow create: if isMeetingMember(mid) && request.resource.data.from == request.auth.uid\n          && str(request.resource.data.payload, 8000);\n        allow update, delete: if false;\n      }\n    }\n  }\n}\n";
